// Real browser File API + actual multi-page PDF bytes; Core events are labelled fixtures.
async (page, { outputDir }) => {
  const checks = [];
  const check = (value, label) => { if (!value) throw new Error(label); checks.push(label); };
  const shot = async (name) => { await page.mouse.move(0, 0); await page.waitForTimeout(220); await page.screenshot({ path: `${outputDir}/preview-${name}.png`, fullPage: true }); };
  const makePdf = () => {
    const objects = ['<< /Type /Catalog /Pages 2 0 R >>', '<< /Type /Pages /Kids [3 0 R 5 0 R] /Count 2 >>', '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 7 0 R >> >> /Contents 4 0 R >>'];
    const stream = (text) => { const value = `BT /F1 24 Tf 50 760 Td (${text}) Tj ET`; return `<< /Length ${value.length} >>\nstream\n${value}\nendstream`; };
    objects.push(stream('FORGE Preview - Page 1'), '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 7 0 R >> >> /Contents 6 0 R >>', stream('FORGE Preview - Page 2'), '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
    let pdf = '%PDF-1.4\n', offsets = [0];
    objects.forEach((object, index) => { offsets.push(Buffer.byteLength(pdf)); pdf += `${index + 1} 0 obj\n${object}\nendobj\n`; });
    const start = Buffer.byteLength(pdf); pdf += `xref\n0 8\n0000000000 65535 f \n${offsets.slice(1).map((offset) => `${String(offset).padStart(10, '0')} 00000 n \n`).join('')}trailer\n<< /Size 8 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;
    return Buffer.from(pdf);
  };
  const markdown = '# FORGE 文件预览\n\n来自真实选择的文件。\n\n[打开源码](source.ts)\n\n[危险链接](javascript:alert(1))\n\n![外链图片](https://forbidden.invalid/image.png)\n\n<script>window.previewUnsafe=true</script>\n\n' + Array.from({ length: 90 }, (_, index) => `段落 ${index}：保留 Markdown 的阅读位置。\n`).join('\n');
  const code = Array.from({ length: 1200 }, (_, index) => `export const line${index} = "row ${index}";`).join('\n');
  let unsafeRequests = 0;
  page.on('request', (request) => { if (request.url().includes('forbidden.invalid')) unsafeRequests += 1; });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://127.0.0.1:5173/');
  await page.getByRole('button', { name: '查看工作空间文件', exact: true }).click();
  const preview = page.getByLabel('工作空间文件预览', { exact: true });
  await preview.getByRole('heading', { name: '工作空间文件' }).waitFor();
  check(await preview.isVisible(), 'preview opens on demand with a genuine browser import entry');
  await page.getByLabel('消息内容', { exact: true }).fill('保留的草稿');
  await page.getByLabel('选择预览文件', { exact: true }).setInputFiles([
    { name: 'README.md', mimeType: 'text/markdown', buffer: Buffer.from(markdown) },
    { name: 'source.ts', mimeType: 'text/plain', buffer: Buffer.from(code) },
    { name: 'report.pdf', mimeType: 'application/pdf', buffer: makePdf() },
    { name: 'legacy.txt', mimeType: 'text/plain', buffer: Buffer.from([0xff, 0xfe, 0x00, 0x00]) },
  const divider = page.getByRole('separator', { name: '调整文件预览宽度' });
  await divider.focus(); await divider.press('ArrowLeft');
  check(await divider.getAttribute('aria-valuenow') === '58', 'splitter supports keyboard resizing');
  const bounds = await divider.boundingBox();
  await page.mouse.move(bounds.x + 2, bounds.y + 20); await page.mouse.down(); await page.mouse.move(bounds.x - 60, bounds.y + 20); await page.mouse.up();
  check(Number(await divider.getAttribute('aria-valuenow')) > 58, 'splitter supports pointer resizing');
  await preview.getByRole('tab', { name: 'README.md', exact: true }).click();
  await shot('markdown-light');
  await preview.locator('.file-tree-row').filter({ hasText: 'report.pdf' }).click();
  const object = preview.locator('object[type="application/pdf"]');
  await object.waitFor(); await page.waitForTimeout(1200);
  check((await object.getAttribute('data')).startsWith('blob:'), 'PDF receives actual imported bytes through an owned Blob URL');
  const downloaded = page.waitForEvent('download'); await preview.getByRole('link', { name: '下载 PDF', exact: true }).click();
  const download = await downloaded;
  check(download.suggestedFilename() === 'report.pdf', 'PDF provides a real downloadable document');
  await shot('pdf-light');
  await preview.locator('.file-tree-row').filter({ hasText: 'legacy.txt' }).click();
  await preview.getByRole('alert').waitFor();
  check((await preview.getByRole('alert').innerText()).includes('UTF-8'), 'unsupported text encoding has an explicit error');
  await preview.getByRole('tab', { name: 'README.md', exact: true }).click();
  await page.evaluate(() => document.documentElement.dataset.theme = 'dark'); await shot('markdown-dark');
  await page.setViewportSize({ width: 900, height: 700 });
  check(!(await page.locator('.conversation-shell').isVisible()), 'narrow windows show one readable file workspace');
  check(await preview.isVisible() && !(await divider.isVisible()), 'narrow layout hides the split drag handle');
  await shot('narrow');
  await preview.getByRole('button', { name: '关闭文件预览', exact: true }).click();
  check(await page.getByLabel('消息内容', { exact: true }).inputValue() === '保留的草稿', 'closing preview restores the original draft');
  check(await page.locator('.conversation-shell').isVisible(), 'closing preview restores chat');
  await page.setViewportSize({ width: 1440, height: 900 }); await page.evaluate(() => delete document.documentElement.dataset.theme);
  await page.getByRole('button', { name: '查看工作空间文件', exact: true }).click();
  check(await preview.getByRole('tab').count() === 4, 'closing and reopening preview retains tabs');
  check(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1), 'file workspace never overflows the window');
  check(await page.evaluate(() => localStorage.length === 0 && sessionStorage.length === 0), 'preview persists no browser storage');
  return { checks: checks.length, screenshots: 5, data: 'real File API imports; two-page PDF', results: checks };
}
